function svg(title){title=esc(title);return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="675" viewBox="0 0 1200 675"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#080609"/><stop offset=".52" stop-color="#201019"/><stop offset="1" stop-color="#5a1832"/></linearGradient><radialGradient id="r" cx="70%" cy="30%"><stop stop-color="#c7a76a" stop-opacity=".20"/><stop offset="1" stop-color="#000" stop-opacity="0"/></radialGradient></defs><rect width="1200" height="675" fill="url(#g)"/><rect width="1200" height="675" fill="url(#r)"/><path d="M850 120h180a100 100 0 0 1 100 100v330H750V220a100 100 0 0 1 100-100z" fill="none" stroke="#c9ad78" stroke-width="3" opacity=".72"/><path d="M796 550V252a126 126 0 0 1 252 0v298" fill="none" stroke="#7e304d" stroke-width="12" opacity=".5"/><circle cx="1012" cy="336" r="7" fill="#d6bb84"/><text x="76" y="95" fill="#d6bb84" font-family="Georgia,serif" font-size="24" letter-spacing="6">CERCLE LIBERTIN</text><line x1="76" y1="126" x2="430" y2="126" stroke="#7e304d" stroke-width="2"/><foreignObject x="76" y="198" width="620" height="300"><div xmlns="http://www.w3.org/1999/xhtml" style="font:700 56px/1.08 Georgia,serif;color:#fff;letter-spacing:-1px">${title}</div></foreignObject><text x="78" y="590" fill="#cbbda9" font-family="Arial,sans-serif" font-size="22">Culture • Clubs • Rencontres • Guides</text><text x="78" y="626" fill="#8f7f72" font-family="Arial,sans-serif" font-size="16">Média indépendant · 18+</text></svg>`}
const imageCache=new Map();
function headers(type,cache){return {"content-type":type,"x-content-type-options":"nosniff","referrer-policy":"strict-origin-when-cross-origin","permissions-policy":"camera=(), microphone=(), geolocation=()","content-security-policy":"default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self'; font-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'; upgrade-insecure-requests","cache-control":cache||"public, max-age=300","x-frame-options":"DENY"}}
http.createServer(async(req,res)=>{try{const u=new URL(req.url,"http://x");let p=decodeURIComponent(u.pathname);const forwardedProto=String(req.headers["x-forwarded-proto"]||"https").split(",")[0].trim();const decision=canonicalizeRequest({host:req.headers.host||"",proto:forwardedProto,pathname:p});if(decision.action==="redirect"){res.writeHead(decision.status,{"location":decision.location,"cache-control":"public, max-age=86400"});return res.end();}p=decision.pathname;if(p==="/health"){res.writeHead(200,{"content-type":"text/plain; charset=utf-8","cache-control":"no-store"});return res.end("ok");}if(p==="/")p="/index.html";if(p.includes("..")){res.writeHead(403);return res.end("forbidden");}if(/^\/assets\/[^/]+\.webp$/.test(p)){const slug=PathSafe(p.split('/').pop().replace(/\.webp$/,''));const title=imageTitles[slug]||slug.replace(/-/g,' ');let buf=imageCache.get(slug);if(!buf){buf=await sharp(Buffer.from(svg(title))).webp({quality:88,effort:5}).toBuffer();imageCache.set(slug,buf);}res.writeHead(200,headers("image/webp","public, max-age=31536000, immutable"));return res.end(buf);}const key=p.replace(/^\//,"");if(Object.prototype.hasOwnProperty.call(files,key)){const ext=(key.match(/\.[^.]+$/)||[""])[0];const cache=(ext===".css"||ext===".js")?"public, max-age=31536000, immutable":"public, max-age=300";let body=files[key];if(ext===".html"||ext===".xml"||ext===".txt"){body=String(body).replaceAll("https://cerclelibertin.com","https://echangismerencontre.com").replaceAll("cerclelibertin.com","echangismerencontre.com");if(key==="404.html"){body=body.replace(/<meta name="robots" content="[^"]*">/,'<meta name="robots" content="noindex,follow,max-image-preview:large">');}}res.writeHead(200,headers(types[ext]||"application/octet-stream",cache));return res.end(body);}res.writeHead(404,headers("text/html; charset=utf-8","no-cache"));let nf=String(files["404.html"]||"Not found").replaceAll("https://cerclelibertin.com","https://echangismerencontre.com").replaceAll("cerclelibertin.com","echangismerencontre.com").replace(/<meta name="robots" content="[^"]*">/,'<meta name="robots" content="noindex,follow,max-image-preview:large">');return res.end(nf);}catch(e){console.error(e);res.writeHead(500,{"content-type":"text/plain; charset=utf-8"});res.end("Internal error");}}).listen(port,"0.0.0.0",()=>console.log("Cercle Libertin listening on",port));
function PathSafe(s){return String(s).replace(/[^a-z0-9-]/gi,"").slice(0,120)||"hero-home";}
